/*
 * Constructor.
 */

pub unsafe extern "C" fn minitiff_init_info(mut info_ptr:
                                                *mut minitiff_info) {
    memset(info_ptr as *mut std::os::raw::c_void, 0 as std::os::raw::c_int,
           ::std::mem::size_of::<minitiff_info>() as std::os::raw::c_ulong);
    (*info_ptr).photometric = -(1 as std::os::raw::c_int) as std::os::raw::c_uint;
}
/*
 * Validator.
 */

pub fn minitiff_validate_info(info: &minitiff_info) {
    if info.width == 0 || info.height == 0 {
        minitiff_error(info,
                       std::ffi::CStr::from_bytes_with_nul(b"Invalid image dimensions in TIFF file\x00")
                           .unwrap());
    }
    if info.bits_per_sample == 0 || info.samples_per_pixel == 0 {
        minitiff_error(info,
                       std::ffi::CStr::from_bytes_with_nul(b"Invalid pixel info in TIFF file\x00")
                           .unwrap());
    }
    if info.strip_offsets.is_null() || info.rows_per_strip == 0 {
        minitiff_error(info,
                       std::ffi::CStr::from_bytes_with_nul(b"Invalid strip info in TIFF file\x00")
                           .unwrap());
    }
    if info.compression != MINITIFF_COMPRESSION_NONE {
        minitiff_error(info,
                       std::ffi::CStr::from_bytes_with_nul(b"Unsupported compression method in TIFF file\x00")
                           .unwrap());
    }
    if info.photometric >= MINITIFF_PHOTOMETRIC_PALETTE {
        minitiff_error(info,
                       std::ffi::CStr::from_bytes_with_nul(b"Unsupported photometric interpretation in TIFF file\x00")
                           .unwrap());
    }
}

/*
 * Destructor.
 */

pub fn minitiff_destroy_info(info: &mut minitiff_info) {
    if !info.strip_offsets.is_null() {
        unsafe {
            // Assuming strip_offsets is a raw pointer, we need to convert it to a safe type
            let _ = Box::from_raw(info.strip_offsets); // This will deallocate the memory when it goes out of scope
        }
        info.strip_offsets = std::ptr::null_mut(); // Set the pointer to null to avoid dangling pointer
    }
}

/*
 * Error handling utility.
 */
fn default_error_handler(msg: &str) {
    eprintln!("minitiff: error: {}", msg);
    std::process::exit(1);
}

/*
 * Error handler.
 */

pub fn minitiff_error(info_ptr: &minitiff_info, msg: &std::ffi::CStr) {
    if let Some(handler) = info_ptr.error_handler {
        unsafe {
            handler(msg.as_ptr());
        }
    } else {
        default_error_handler(msg.to_str().unwrap());
    }
    std::process::abort();
}

/*
 * Warning handling utility.
 */
fn default_warning_handler(msg: &str) {
    eprintln!("minitiff: warning: {}", msg);
}

/*
 * Warning handler.
 */

pub fn minitiff_warning(info_ptr: &minitiff_info, msg: &std::ffi::CStr) {
    if let Some(handler) = info_ptr.warning_handler {
        unsafe {
            handler(msg.as_ptr());
        }
    } else {
        default_warning_handler(msg.to_str().expect("Invalid UTF-8 string"));
    }
}

