                let unknown_chunk = &*image.unknowns.offset(i as isize); // Convert raw pointer to reference
                png_set_unknown_chunk_location(png_ptr, info_ptr, i, unknown_chunk.location as i32); // Convert u8 to i32
                i += 1;
