/* ========================================================================
 * Tables of CRC-32s of all single-byte values, made by make_crc_table().
 */
/* DYNAMIC_CRC_TABLE */
/* =========================================================================
 * This function can be used by asm versions of crc32()
 */

pub fn get_crc_table() -> &'static [[z_crc_t; 256]; 8] {
    unsafe { &crc_table }
}

/* ========================================================================= */
/* ========================================================================= */

pub fn crc32_z(crc: u64, buf: &[u8], len: usize) -> u64 {
    if buf.is_empty() { return 0 }

    let mut crc = crc ^ 0xffffffff;
    let mut len = len;

    let mut index = 0;

    while len >= 8 {
        for _ in 0..8 {
            crc = unsafe { crc_table[0][((crc as u32 ^ buf[index] as u32) & 0xff) as usize] as u64 ^ (crc >> 8) };
            index += 1;
        }
        len -= 8;
    }

    for _ in 0..len {
        crc = unsafe { crc_table[0][((crc as u32 ^ buf[index] as u32) & 0xff) as usize] as u64 ^ (crc >> 8) };
        index += 1;
    }

    crc ^ 0xffffffff
}

/* ========================================================================= */

pub unsafe extern "C" fn crc32(mut crc: std::os::raw::c_ulong,
                               mut buf: *const std::os::raw::c_uchar, mut len: uInt)
 -> uLong {
    return crc32_z(crc, unsafe { std::slice::from_raw_parts(buf, len as usize) }, len as usize);
}
